# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Consumer-perspective tests for the public API.
//!
//! These exercise only what is re-exported from the crate root, so they fail if
//! the export surface regresses even when the internals still compile.

use tinybox_core::{
    BoxSpec, BoxState, Capability, Error, ExecOutput, ExecRequest, HostRef, IsolationLevel,
    Lifecycle, NetworkPolicy, Placement, Resources, Result, SandboxCapabilities, SandboxRef,
    SnapshotId, SnapshotSupport, WorkspaceSource,
};

/// Build a placement, propagating identifier validation failures to the test.
fn placement(host: &str, sandbox: &str) -> Result<Placement> {
    Ok(Placement::new(
        HostRef::new(host)?,
        SandboxRef::new(sandbox)?,
    ))
}

#[test]
fn the_model_is_reachable_from_the_crate_root() -> Result<()> {
    let spec = BoxSpec::new(
        placement("local", "docker")?,
        WorkspaceSource::OciImage("alpine:3".to_owned()),
    );

    assert!(spec.validate().is_ok());
    assert!(spec.is_colocated());
    assert_eq!(spec.resources, Resources::DEFAULT);
    assert_eq!(spec.network, NetworkPolicy::Denied);
    assert!(spec.lifecycle.is_ephemeral());
    Ok(())
}

#[test]
fn reach_and_confinement_are_chosen_independently() -> Result<()> {
    let spec = BoxSpec::new(
        placement("builder-01", "docker")?,
        WorkspaceSource::Snapshot(SnapshotId::new("base-1")?),
    )
    .with_runner(placement("local", "passthrough")?)
    .with_lifecycle(Lifecycle::persistent());

    assert!(!spec.is_colocated());
    assert!(!spec.runner.shares_host(&spec.workspace));
    assert_eq!(spec.workspace.host.as_str(), "builder-01");
    assert!(spec.lifecycle.autosnapshot_interval().is_some());
    Ok(())
}

#[test]
fn a_backend_refuses_capabilities_it_does_not_declare() {
    let passthrough = SandboxCapabilities::PASSTHROUGH;

    assert_eq!(passthrough.isolation, IsolationLevel::None);
    assert!(!passthrough.is_suitable_for_untrusted_code());

    assert!(matches!(
        passthrough.require("passthrough", Capability::FilesystemSnapshot),
        Err(Error::Unsupported { .. })
    ));
}

#[test]
fn a_container_backend_snapshots_disk_but_not_memory() {
    let docker = SandboxCapabilities::new(IsolationLevel::Kernel, SnapshotSupport::Filesystem)
        .with_fork()
        .with_port_forward()
        .with_resource_limits();

    assert!(docker.is_suitable_for_untrusted_code());
    assert!(docker.supports(Capability::FilesystemSnapshot));
    assert!(!docker.supports(Capability::MemorySnapshot));
}

#[test]
fn invalid_input_is_rejected_at_the_boundary() -> Result<()> {
    assert!(HostRef::new("../escape").is_err());
    assert!(SandboxRef::new("").is_err());

    let outcome = BoxSpec::new(
        placement("local", "docker")?,
        WorkspaceSource::OciImage("alpine:3".to_owned()),
    )
    .with_resources(Resources {
        memory_bytes: 0,
        ..Resources::DEFAULT
    })
    .validate();

    assert!(matches!(
        outcome,
        Err(Error::ZeroResourceLimit {
            limit: "memory_bytes"
        })
    ));
    Ok(())
}

#[test]
fn commands_and_their_results_are_consumer_visible() {
    let request = ExecRequest::new(["cargo", "test"]).with_env("RUST_BACKTRACE", "1");
    assert_eq!(request.program(), Some("cargo"));

    let output = ExecOutput::new(0, b"ok".to_vec(), Vec::new());
    assert!(output.succeeded());
    assert_eq!(output.stdout_lossy(), "ok");

    assert!(BoxState::Ready.accepts_commands());
    assert!(!BoxState::Archived.is_live());
}

//! End-to-end tests that drive the real `tinybox` binary.
//!
//! Everything else in this crate tests `tinybox_cli::run` in-process, which
//! cannot exercise `main.rs` — the runtime setup, the stream locking, and the
//! conversion of a code into a process exit status. Spawning the binary covers
//! those, and it is also the only test that proves the milestone the way a user
//! meets it: create a box, run something in it, and see the result.
//!
//! `CARGO_BIN_EXE_tinybox` is set by cargo for integration tests, and
//! `cargo llvm-cov` instruments workspace binaries, so this run counts toward
//! coverage rather than leaving `main.rs` uncovered.
//!
//! Tests return `io::Result` and use `?` rather than `expect`, because the
//! no-panic lints apply to every target in this workspace.

use std::io;
use std::path::Path;
use std::process::{Command, Output};

use tempfile::TempDir;

/// Run the real binary with a store inside `dir`.
fn tinybox(dir: &Path, args: &[&str]) -> io::Result<Output> {
    Command::new(env!("CARGO_BIN_EXE_tinybox"))
        .arg("--store")
        .arg(dir.join("boxes.json"))
        .args(args)
        .output()
}

fn stdout(output: &Output) -> String {
    String::from_utf8_lossy(&output.stdout).into_owned()
}

fn stderr(output: &Output) -> String {
    String::from_utf8_lossy(&output.stderr).into_owned()
}

#[test]
fn a_box_is_created_used_and_destroyed_through_the_binary() -> io::Result<()> {
    let state = TempDir::new()?;
    let workspace = TempDir::new()?;
    let workspace_path = workspace.path().display().to_string();

    let created = tinybox(state.path(), &["create", "--dir", &workspace_path])?;
    assert!(created.status.success(), "{}", stderr(&created));
    assert_eq!(stdout(&created).trim(), "box-0");

    // A separate process, reading the box the first one recorded.
    let executed = tinybox(state.path(), &["exec", "box-0", "echo", "from-the-box"])?;
    assert!(executed.status.success(), "{}", stderr(&executed));
    assert_eq!(stdout(&executed).trim(), "from-the-box");

    let listed = tinybox(state.path(), &["ls"])?;
    assert!(stdout(&listed).contains("box-0"));

    let removed = tinybox(state.path(), &["rm", "box-0"])?;
    assert!(removed.status.success());
    assert!(stdout(&tinybox(state.path(), &["ls"])?).is_empty());
    Ok(())
}

#[test]
fn the_command_exit_status_becomes_the_process_exit_status() -> io::Result<()> {
    let state = TempDir::new()?;

    let executed = tinybox(
        state.path(),
        &["run", "--dir", "/tmp", "sh", "-c", "exit 9"],
    )?;

    // A code that is not forwarded shows up here and nowhere else.
    assert_eq!(executed.status.code(), Some(9));
    Ok(())
}

#[test]
fn output_survives_being_piped() -> io::Result<()> {
    let state = TempDir::new()?;

    let executed = tinybox(
        state.path(),
        &["run", "--dir", "/tmp", "sh", "-c", "echo piped"],
    )?;

    // Not a terminal, so stdout is block-buffered; this fails if `main` exits
    // without flushing.
    assert_eq!(stdout(&executed).trim(), "piped");
    assert!(executed.status.success());
    Ok(())
}

#[test]
fn a_tinybox_failure_is_distinguishable_from_a_command_failure() -> io::Result<()> {
    let state = TempDir::new()?;

    let missing = tinybox(state.path(), &["exec", "box-9", "true"])?;
    assert_eq!(missing.status.code(), Some(70));
    assert!(stderr(&missing).contains("no box with id box-9"));

    let failed = tinybox(
        state.path(),
        &["run", "--dir", "/tmp", "sh", "-c", "exit 1"],
    )?;
    assert_eq!(failed.status.code(), Some(1));
    Ok(())
}

#[test]
fn help_reaches_stdout_and_names_every_command() -> io::Result<()> {
    let state = TempDir::new()?;

    let help = tinybox(state.path(), &["--help"])?;

    assert!(help.status.success());
    // On stdout, not stderr, or `tinybox --help | less` comes back empty.
    let text = stdout(&help);
    for command in ["create", "exec", "ls", "inspect", "rm", "run"] {
        assert!(text.contains(command), "help should mention {command}");
    }
    Ok(())
}

#[test]
fn the_default_store_location_is_used_when_none_is_given() -> io::Result<()> {
    let state = TempDir::new()?;

    // No `--store`, so the path comes from the environment. Setting it on the
    // child avoids mutating this process's own environment, which would need
    // `unsafe` in Rust 2024.
    let created = Command::new(env!("CARGO_BIN_EXE_tinybox"))
        .env("TINYBOX_STATE_DIR", state.path())
        .args(["create", "--dir", "/tmp"])
        .output()?;

    assert!(created.status.success(), "{}", stderr(&created));
    assert_eq!(stdout(&created).trim(), "box-0");
    assert!(state.path().join("boxes.json").exists());
    Ok(())
}
